from itertools import combinations

def check_graph(n, edges):
    G = nx.Graph()
    G.add_nodes_from(range(n))
    G.add_edges_from(edges)

    # Check girth
    try:
        girth = nx.girth(G)
    except:
        # If no cycle, girth is infinity
        girth = float('inf')

    # Check chromatic number
    # For small graphs, we can use greedy coloring or just check if it's 4-colorable
    # nx.coloring.greedy_color is an approximation, but for small graphs, 
    # we can use a backtracking approach or just check if it's 4-colorable.
    # Actually, for 16 vertices, we can use a solver or just check if it's 4-colorable.

    # Let's use a simple backtracking coloring
    def is_k_colorable(graph, k):
        coloring = {}
        def solve(node):
            if node == n:
                return True
            for color in range(k):
                if all(coloring.get(neighbor) != color for neighbor in graph.neighbors(node)):
                    coloring[node] = color
                    if solve(node + 1):
                        return True
                    del coloring[node]
            return False
        return solve(0)

    return girth, is_k_colorable(G, 4), G.number_of_edges()

